const crypto = require('crypto');

// 6-digit PIN - enough friction for a client typing it in by hand, not meant to be a
// high-entropy secret (this is document-folder access for an already-paying client, not a
// financial credential). crypto.randomInt is a CSPRNG, not Math.random - no reason to use a
// weaker generator just because the entropy target itself is low.
const pin = String(crypto.randomInt(0, 1000000)).padStart(6, '0');
const pinHash = crypto.createHash('sha256').update(pin, 'utf8').digest('hex');

return [{ json: { plaintextPin: pin, pinHash } }];
